    "code": {"type": "string", "default": "import datetime

WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']
HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('cannot read now: ' + s)

def parse_holidays(values):
    out = set()
    for v in values or []:
        try:
            out.add(datetime.date.fromisoformat(str(v)[:10]))
        except ValueError:
            pass
    return out

def is_business_day(d, holidays):
    return d.weekday() < 5 and d not in holidays

def next_business_day(d, holidays, include_today=False):
    if include_today and is_business_day(d, holidays):
        return d
    d = d + datetime.timedelta(days=1)
    while not is_business_day(d, holidays):
        d = d + datetime.timedelta(days=1)
    return d

def spoken_date(d):
    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()

try:
    now = parse_now(vars.get('now'))
    hol = parse_holidays(HOL)
    today = now.date()
    hm = now.strftime('%H:%M')
    nxt = next_business_day(today, hol)
    parts = []
    if is_business_day(today, hol) and hm < '19:00':
        start = ('later than ' + hm) if hm >= '10:00' else 'from 10:00'
        parts.append('today, ' + spoken_date(today) + ' (' + today.isoformat() + '), ' + start + ' up to 19:00')
    parts.append(spoken_date(nxt) + ' (' + nxt.isoformat() + '), from 10:00 to 19:00')
    vars['callback_window_text'] = 'It is now ' + spoken_date(today) + ', ' + hm + '. A callback can only be booked ' + ' or on '.join(parts) + ', both times included. Any other day or time is outside the window.'
    vars['today_iso'] = today.isoformat()
except Exception:
    vars['callback_window_text'] = 'A callback can only be booked for the next business day, from 10:00 to 19:00.'
    vars['today_iso'] = ''
vars['close_outcome'] = 'not_reached'
vars['close_reason'] = 'unclear'
vars['bye_text'] = 'Thank you for your time. Goodbye.'
vars['promise_count'] = '0'
vars['call_state'] = 'open'
vars['id_state'] = 'open'
vars['cb_state'] = 'open'
vars['topic'] = 'none'
vars['hardship'] = 'no'
vars['transfer_queue'] = 'general'
vars['transfer_reason'] = 'human'
